import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const host=document.querySelector('#world');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9ca99b);scene.fog=new THREE.Fog(0x9ca99b,24,76);
const camera=new THREE.PerspectiveCamera(76,innerWidth/innerHeight,.1,120);camera.position.set(0,1.65,8);
const renderer=new THREE.WebGLRenderer({antialias:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,.85));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.BasicShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;host.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xdce9d3,0x35433b,2.1));const sun=new THREE.DirectionalLight(0xffd5a1,2.25);sun.position.set(-14,24,13);sun.castShadow=true;sun.shadow.mapSize.set(512,512);sun.shadow.camera.left=-30;sun.shadow.camera.right=30;sun.shadow.camera.top=30;sun.shadow.camera.bottom=-30;scene.add(sun);
const mats={ground:new THREE.MeshLambertMaterial({color:0x697568}),wall:new THREE.MeshLambertMaterial({color:0x59645b}),dark:new THREE.MeshLambertMaterial({color:0x303b35}),crate:new THREE.MeshLambertMaterial({color:0x9a8058}),crate2:new THREE.MeshLambertMaterial({color:0x726043}),metal:new THREE.MeshLambertMaterial({color:0x727d73}),orange:new THREE.MeshLambertMaterial({color:0xd56d3a}),lime:new THREE.MeshLambertMaterial({color:0xc8f169}),zombie:new THREE.MeshLambertMaterial({color:0x64806a}),skin:new THREE.MeshLambertMaterial({color:0x98a17b}),red:new THREE.MeshLambertMaterial({color:0x9d503d}),blue:new THREE.MeshLambertMaterial({color:0x526c77})};
function box(parent,x,y,z,w,h,d,mat,shadow=true){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=shadow;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,rt,rb,h,mat,seg=6){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,seg),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
const ground=new THREE.Mesh(new THREE.PlaneGeometry(90,90),mats.ground);ground.rotation.x=-Math.PI/2;ground.position.y=-.04;ground.receiveShadow=true;scene.add(ground);
// Concrete perimeter and a compact blockyard of cover.
for(let i=-1;i<=1;i++){box(scene,i*24,2.3,-24,18,4.6,1,mats.wall);box(scene,i*24,2.3,24,18,4.6,1,mats.wall);box(scene,-24,2.3,i*24,1,4.6,18,mats.wall);box(scene,24,2.3,i*24,1,4.6,18,mats.wall)}
for(const [x,z,w,d,h] of [[-13,-8,7,5,4],[12,-12,6,6,5],[13,9,7,5,3.8],[-12,13,6,7,4.5],[1,-17,9,3,3],[2,15,8,3,2.8]]){box(scene,x,h/2,z,w,h,d,mats.wall);box(scene,x,h+.13,z,w+.15,.25,d+.15,mats.dark);for(let yy=1.1;yy<h-1;yy+=1.2)box(scene,x,yy,z-d/2-.02,w*.55,.18,.06,mats.metal,false)}
const cover=[];
for(const [x,z,s] of [[-6,-6,1.25],[5,-7,1.5],[-3,5,1.1],[8,3,1.4],[-8,10,1.3],[1,10,1.5],[15,-2,1.1],[-15,0,1.3],[4,-15,1.3],[-1,-1,1.1],[11,14,1.1]]){const c=box(scene,x,s*.55,z,s*1.6,s*1.1,s*1.5,Math.random()>.5?mats.crate:mats.crate2);cover.push({x,z,scale:s,mesh:c});for(let k=-1;k<=1;k++)box(scene,x+k*s*.45,s*.55,z-s*.76,.07,s*.8,.035,mats.dark,false)}
// Yard clutter: barrels, pallets, lamps and warning marks.
for(const [x,z] of [[-17,-14],[17,13],[15,-19],[-18,17],[6,0],[-4,-13]]){cylinder(scene,x,.65,z,.55,.55,1.3,mats.orange,8);cylinder(scene,x,.5,z,.57,.57,.12,mats.dark,8);cylinder(scene,x,1.12,z,.57,.57,.12,mats.dark,8)}
for(const [x,z] of [[-19,-4],[20,5],[-2,21],[4,-22]]){box(scene,x,2.5,z,.16,5,.16,mats.dark);box(scene,x,4.8,z,.8,.42,.55,mats.orange);}
// painted lane dashes
for(let i=-4;i<=4;i++)box(scene,i*2,.006,0,.8,.012,.07,mats.lime,false);
const clock=new THREE.Clock();let mode='zombie',running=false,dead=false,paused=false,health=100,kills=0,wave=1,score=0,ammo=30,reserve=120,rocketAmmo=4,rocketReserve=12,weapon='ak',reloading=false,spawnTimer=1,propTimer=90,mouseLocked=false,lastShot=0,hitTimeout=0,toastTimeout=0;
const player={x:0,z:8,yaw:0,pitch:0,speed:5.2};const keys={};let touchMove={x:0,y:0};
const enemies=[],ragdolls=[],rockets=[],particles=[];let playerProp=null,enemyCount=0;
function makeProp(type,x,y,z,scale=1){const g=new THREE.Group();g.position.set(x,y,z);scene.add(g);let material=type==='barrel'?mats.orange:type==='crate'?mats.crate:mats.crate2;if(type==='barrel'){cylinder(g,0,.55,0,.42,.42,1.1,material,8);cylinder(g,0,.12,0,.44,.44,.1,mats.dark,8);cylinder(g,0,1,0,.44,.44,.1,mats.dark,8)}else{box(g,0,.52,0,.9,1,.9,material);for(let a of [-.3,0,.3])box(g,a,.52,-.457,.04,.86,.025,mats.dark,false)}g.scale.setScalar(scale);g.userData.type=type;return g}
function makeDude(isHunter=false){const g=new THREE.Group();const body=box(g,0,1.05,0,.62,.9,.35,isHunter?mats.blue:mats.zombie),head=box(g,0,1.72,-.02,.42,.42,.4,isHunter?mats.skin:mats.skin),armL=box(g,-.42,1.08,0,.22,.78,.25,isHunter?mats.blue:mats.red),armR=box(g,.42,1.08,0,.22,.78,.25,isHunter?mats.blue:mats.red),legL=box(g,-.18,.38,0,.25,.68,.3,mats.dark),legR=box(g,.18,.38,0,.25,.68,.3,mats.dark);box(g,0,1.72,-.235,.28,.08,.04,mats.orange,false);g.userData.parts=[body,head,armL,armR,legL,legR];g.userData.hunter=isHunter;return g}
function spawnEnemy(hunter=false){const g=makeDude(hunter);let a=Math.random()*Math.PI*2,r=14+Math.random()*7;g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);scene.add(g);enemies.push({g,hp:hunter?2:3,speed:hunter?2.3:1.15+Math.random()*.55,attack:0,hunter,alive:true});enemyCount++}
function setToast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.opacity='1';clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.style.opacity='0',1500)}
function setMode(m){mode=m;document.querySelectorAll('.mode-card').forEach(e=>e.classList.toggle('active',e.dataset.mode===m));}
document.querySelectorAll('.mode-card').forEach(e=>e.onclick=()=>setMode(e.dataset.mode));
function startGame(){document.querySelector('#overlay').classList.add('hidden');document.querySelector('#hud').classList.add('on');document.querySelector('#end-screen').style.display='none';document.querySelector('#mobile').style.display='block';running=true;dead=false;paused=false;health=100;kills=0;score=0;wave=1;ammo=30;reserve=120;rocketAmmo=4;rocketReserve=12;reloading=false;spawnTimer=1;propTimer=90;player.x=0;player.z=8;player.yaw=0;player.pitch=0;weapon='ak';enemies.forEach(e=>scene.remove(e.g));enemies.length=0;ragdolls.splice(0).forEach(r=>r.parts.forEach(p=>scene.remove(p)));rockets.splice(0).forEach(r=>scene.remove(r.mesh));if(playerProp){scene.remove(playerProp);playerProp=null}if(mode==='zombie'){for(let i=0;i<5;i++)spawnEnemy(false);document.querySelector('#wave-label').textContent='WAVE';document.querySelector('#objective').innerHTML='OBJECTIVE<strong>ELIMINATE HOSTILES</strong>';document.querySelector('#count-label').textContent='HOSTILES DOWN';setToast('WAVE 01 — THEY HEAR YOU')}else{for(let i=0;i<6;i++)spawnEnemy(true);playerProp=makeProp('barrel',player.x,0,player.z,1.05);document.querySelector('#wave-label').textContent='TIME';document.querySelector('#wave').textContent='90';document.querySelector('#objective').innerHTML='OBJECTIVE<strong>STAY UNDISCOVERED</strong>';document.querySelector('#count-label').textContent='HUNTERS LURED';setToast('BLEND IN. MOVE QUIETLY.')}updateUI();requestLock()}
document.querySelector('#start').onclick=startGame;document.querySelector('#again').onclick=()=>{document.querySelector('#overlay').classList.remove('hidden');document.querySelector('#end-screen').style.display='none';document.querySelector('#hud').classList.remove('on');running=false;document.exitPointerLock?.()};
function requestLock(){if(innerWidth>700)renderer.domElement.requestPointerLock?.()}
document.addEventListener('pointerlockchange',()=>{mouseLocked=document.pointerLockElement===renderer.domElement;if(!mouseLocked&&running&&innerWidth>700)paused=true;else paused=false});

