document.addEventListener('pointerlockchange',()=>{mouseLocked=document.pointerLockElement===renderer.domElement;if(!mouseLocked&&running&&innerWidth>700)paused=true;else paused=false});
document.addEventListener('mousemove',e=>{if(!running||!mouseLocked)return;player.yaw-=e.movementX*.0022;player.pitch=Math.max(-1.25,Math.min(1.25,player.pitch-e.movementY*.0022))});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!running)return;if(e.code==='Digit1')setWeapon('ak');if(e.code==='Digit2')setWeapon('rpg');if(e.code==='KeyR')reload();if(e.code==='KeyF'&&mode==='prop')changeProp();if(e.code==='Escape'&&paused)setToast('CLICK TO RESUME')});document.addEventListener('keyup',e=>keys[e.code]=false);
renderer.domElement.addEventListener('click',()=>{if(running&&innerWidth>700&&!mouseLocked)requestLock();else if(running)fire()});
function setWeapon(w){weapon=w;document.querySelector('#weapon-art').style.display=mode==='prop'?'none':'block';document.querySelector('#weapon-name').textContent=w==='ak'?'AK-47':'RPG-7';document.querySelector('#weapon-art').innerHTML=w==='ak'?'<path fill="#252d28" d="M38 81h185l22-22 40 4 22 17h37v26h-66l-18 25h-63l-22-20H95l-32 19H22V99h16z"/><path fill="#485348" d="M43 69h187l12 13-15 17H48z"/><path fill="#a27a48" d="M87 95h61l-7 32-52 3-17-10zM232 63h35l27 17h-59z"/><path fill="#141a17" d="M151 94h17l5 52h-16zM212 91h12l-2 37h-12zM294 82h27v6h-27z"/><path fill="#69766b" d="M58 67h134v7H58zM195 74h38v10h-38z"/><circle cx="94" cy="82" r="3" fill="#d5d9c9"/>':'<path fill="#303833" d="M18 82h217l26-17h69v30h-81l-25 16H18z"/><path fill="#5b665e" d="M24 70h206v12H24zM246 68h74v7h-74z"/><path fill="#a27a48" d="M54 94h50l-5 34H50z"/><path fill="#141a17" d="M121 93h17v57h-17zM254 94h28v18h-28z"/><circle cx="285" cy="80" r="8" fill="#ff8a4c"/>';document.querySelector('#ammo').textContent=w==='ak'?`${ammo} / ${reserve}`:`${rocketAmmo} / ${rocketReserve}`;}
function reload(){if(!running||reloading)return;if(weapon==='ak'&&ammo<30&&reserve>0){reloading=true;setToast('RELOADING');setTimeout(()=>{if(!running)return;const n=Math.min(30-ammo,reserve);ammo+=n;reserve-=n;reloading=false;updateUI()},1000)}else if(weapon==='rpg'&&rocketAmmo<4&&rocketReserve>0){reloading=true;setToast('RELOADING LAUNCHER');setTimeout(()=>{if(!running)return;const n=Math.min(4-rocketAmmo,rocketReserve);rocketAmmo+=n;rocketReserve-=n;reloading=false;updateUI()},1400)}}
function direction(){return new THREE.Vector3(-Math.sin(player.yaw)*Math.cos(player.pitch),Math.sin(player.pitch),-Math.cos(player.yaw)*Math.cos(player.pitch)).normalize()}
