function blocked(x,z){if(Math.abs(x)>21.6||Math.abs(z)>21.6)return true;const blocks=[[-13,-8,3.8,2.8],[12,-12,3.3,3.3],[13,9,3.8,2.8],[-12,13,3.3,3.8],[1,-17,4.8,2.1],[2,15,4.3,2.1]];for(const [bx,bz,w,d] of blocks)if(Math.abs(x-bx)<w+.38&&Math.abs(z-bz)<d+.38)return true;for(const c of cover)if(Math.abs(x-c.x)<c.scale*1.1&&Math.abs(z-c.z)<c.scale*1.05)return true;return false}
function movePlayer(dt){let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-touchMove.y;let side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touchMove.x;const len=Math.hypot(f,side);if(len>1){f/=len;side/=len}const speed=mode==='prop'?4.8:5.2;const dx=(-Math.sin(player.yaw)*f+Math.cos(player.yaw)*side)*speed*dt,dz=(-Math.cos(player.yaw)*f-Math.sin(player.yaw)*side)*speed*dt;if(!blocked(player.x+dx,player.z))player.x+=dx;if(!blocked(player.x,player.z+dz))player.z+=dz;if(playerProp){playerProp.position.set(player.x,0,player.z);playerProp.rotation.y=player.yaw}}
function updateEnemies(dt){for(const e of enemies){if(!e.alive)continue;const p=e.g.position;let dx=player.x-p.x,dz=player.z-p.z,dist=Math.hypot(dx,dz);if(mode==='prop'&&e.hunter){if(dist>3.5){const angle=Math.atan2(dx,dz);e.g.rotation.y=angle;p.x+=Math.sin(angle)*e.speed*dt;p.z+=Math.cos(angle)*e.speed*dt}else{e.attack-=dt;if(e.attack<=0){e.attack=.7;health-=8;setToast('YOU HAVE BEEN SPOTTED');updateUI();if(health<=0){endGame(false);return}}}}else{if(dist>1.3){const angle=Math.atan2(dx,dz);e.g.rotation.y=angle;let nx=p.x+Math.sin(angle)*e.speed*dt,nz=p.z+Math.cos(angle)*e.speed*dt;if(!blocked(nx,p.z))p.x=nx;if(!blocked(p.x,nz))p.z=nz}else{e.attack-=dt;if(e.attack<=0){e.attack=.9;health-=e.hunter?9:8;updateUI();if(health<=0){endGame(false);return}}}}}}
function updateRagdolls(dt){for(let i=ragdolls.length-1;i>=0;i--){const r=ragdolls[i];r.life+=dt;r.vel.y-=9.8*dt;r.mesh.position.addScaledVector(r.vel,dt);r.mesh.rotation.x+=r.spin.x*dt;r.mesh.rotation.y+=r.spin.y*dt;r.mesh.rotation.z+=r.spin.z*dt;if(r.mesh.position.y<.15){r.mesh.position.y=.15;r.vel.y=Math.abs(r.vel.y)*.22;r.vel.x*=.76;r.vel.z*=.76;r.spin.multiplyScalar(.72)}if(r.life>10){scene.remove(r.mesh);ragdolls.splice(i,1)}}}
function updateRockets(dt){for(let i=rockets.length-1;i>=0;i--){const r=rockets[i];r.life+=dt;r.mesh.position.addScaledVector(r.dir,19*dt);let hitTarget=r.life>1.7||r.mesh.position.y<.2||Math.abs(r.mesh.position.x)>23||Math.abs(r.mesh.position.z)>23;for(const e of enemies)if(e.alive&&e.g.position.distanceTo(r.mesh.position)<1.1)hitTarget=true;if(hitTarget){const pos=r.mesh.position.clone();scene.remove(r.mesh);rockets.splice(i,1);explode(pos)}}}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life+=dt;if(p.explosion){const s=1+p.life*8;p.mesh.scale.setScalar(s);p.mesh.material.opacity=Math.max(0,.8-p.life*1.2)}else{p.mesh.position.y+=dt*2;p.mesh.material.opacity=1-p.life}if(p.life> .7){scene.remove(p.mesh);particles.splice(i,1)}}}
function updateRadar(){const el=document.querySelector('#radar-dots');el.innerHTML='';for(const e of enemies){if(!e.alive)continue;const dx=e.g.position.x-player.x,dz=e.g.position.z-player.z,rot=-player.yaw;const rx=dx*Math.cos(rot)-dz*Math.sin(rot),rz=dx*Math.sin(rot)+dz*Math.cos(rot),dot=document.createElement('i');dot.className='radar-dot';dot.style.left=(50+Math.max(-42,Math.min(42,rx*2.7)))+'%';dot.style.top=(50+Math.max(-42,Math.min(42,rz*2.7)))+'%';if(mode==='prop')dot.style.background='#ff8a4c';el.appendChild(dot)}}
function update(dt){if(!running||paused||dead)return;movePlayer(dt);camera.position.set(player.x,1.65,player.z);camera.rotation.order='YXZ';camera.rotation.set(player.pitch,player.yaw,0);if(mode==='zombie'){if(waveTransition){spawnTimer-=dt;if(spawnTimer<=0){waveTransition=false;for(let i=0;i<Math.min(5+wave*2,18);i++)spawnEnemy(false);setToast(`WAVE ${String(wave).padStart(2,'0')} — ${Math.min(5+wave*2,18)} INBOUND`)}}}else{propTimer-=dt;document.querySelector('#wave').textContent=String(Math.max(0,Math.ceil(propTimer))).padStart(2,'0');if(propTimer<=0){endGame(true);return}}
